// Inlines Leaflet (BSD-2-Clause) into a TS module so the native map WebView needs no CDN.
// Run after upgrading leaflet: node scripts/gen-leaflet.mjs
import fs from 'fs';
const js=fs.readFileSync('node_modules/leaflet/dist/leaflet.js','utf8').replace(/\n\/\/# sourceMappingURL=.*$/,'');
const css=fs.readFileSync('node_modules/leaflet/dist/leaflet.css','utf8');
const ver=JSON.parse(fs.readFileSync('node_modules/leaflet/package.json','utf8')).version;
fs.writeFileSync('src/components/map/leafletAsset.ts',`// Generated by scripts/gen-leaflet.mjs from leaflet@${ver} (BSD-2-Clause, © Volodymyr Agafonkin, CloudMade). Do not edit.\nexport const LEAFLET_JS=${JSON.stringify(js)};\nexport const LEAFLET_CSS=${JSON.stringify(css)};\n`);
